import React, { useState } from 'react';

// Create your App component here
const App = () => {
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const [refreshToken, setRefreshToken] = useState<string | null>(null);
  const [tokenExpiry, setTokenExpiry] = useState<number | null>(null);

  const handleLogin = () => {
    // Simulate login: set tokens and expiry
    setAccessToken('access-token-123');
    setRefreshToken('refresh-token-456');
    setTokenExpiry(Date.now() + 3600000); // 1 hour from now
  };

  const handleRefresh = () => {
    // Simulate token refresh
    setAccessToken('new-access-token-789');
    setTokenExpiry(Date.now() + 3600000);
  };

  return (
    <div>
      <div>
        <h3>Token Status</h3>
        <p>Access Token: {accessToken || 'Not logged in'}</p>
        <p>Refresh Token: {refreshToken || 'Not logged in'}</p>
        <p>Token Expiry: {tokenExpiry ? new Date(tokenExpiry).toLocaleString() : 'N/A'}</p>
      </div>

      {/* Add secure token rotation explanation paragraph here */}

      <button onClick={handleLogin}>Login</button>
      <button onClick={handleRefresh}>Refresh Token</button>
    </div>
  );
};

export default App;
